// Tokens of the setup language (LANGUAGE.md § 1).

export type TokType = 'TIME' | 'NUMBER' | 'PERCENT' | 'PARAM' | 'IDENT' | 'OP' | 'PUNCT' | 'EOF';

export interface Tok {
  type: TokType;
  /** source text */
  text: string;
  /** lowercase text for IDENT and PARAM (without '$'), the canonical operator for OP, HH:MM for TIME */
  v: string;
  /** NUMBER: its value; TIME: minutes after midnight */
  num: number;
  offset: number;
  length: number;
}

export interface LexError {
  code: 'E_UNEXPECTED_CHAR' | 'E_BAD_TIME';
  offset: number;
  length: number;
  tok: string;
}

export const KEYWORDS = [
  'all', 'and', 'or', 'not', 'between', 'in', 'of', 'touches', 'trades', 'closes', 'above', 'below',
  'before', 'then', 'from', 'by', 'within', 'on', 'close', 'session_close',
] as const;
const KEYWORD_SET = new Set<string>(KEYWORDS);
export const isKeyword = (v: string): boolean => KEYWORD_SET.has(v);

const isDigit = (c: string): boolean => c >= '0' && c <= '9';
const isIdentStart = (c: string): boolean => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
const isIdentChar = (c: string): boolean => isIdentStart(c) || isDigit(c);

export function lex(text: string): { toks: Tok[]; error: LexError | null } {
  const toks: Tok[] = [];
  let i = 0;
  const n = text.length;
  const push = (type: TokType, start: number, end: number, v: string, num = 0): void => {
    toks.push({ type, text: text.slice(start, end), v, num, offset: start, length: end - start });
  };
  while (i < n) {
    const c = text[i];
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i++;
      continue;
    }
    // TIME
    const tm = /^[0-9]{1,2}:[0-9]{2}/.exec(text.slice(i, i + 5));
    if (tm) {
      const s = tm[0];
      const [hs, ms] = s.split(':');
      const h = +hs, m = +ms;
      if (h > 23 || m > 59) return { toks, error: { code: 'E_BAD_TIME', offset: i, length: s.length, tok: s } };
      push('TIME', i, i + s.length, (h < 10 ? '0' : '') + h + ':' + ms, h * 60 + m);
      i += s.length;
      continue;
    }
    if (isDigit(c)) {
      let j = i;
      while (j < n && isDigit(text[j])) j++;
      if (text[j] === '.' && isDigit(text[j + 1] ?? '')) {
        j++;
        while (j < n && isDigit(text[j])) j++;
      }
      const s = text.slice(i, j);
      push('NUMBER', i, j, s, Number(s));
      i = j;
      continue;
    }
    if (c === '%') {
      push('PERCENT', i, i + 1, '%');
      i++;
      continue;
    }
    if (c === '$' && isIdentStart(text[i + 1] ?? '')) {
      let j = i + 1;
      while (j < n && isIdentChar(text[j])) j++;
      push('PARAM', i, j, text.slice(i + 1, j).toLowerCase());
      i = j;
      continue;
    }
    if (isIdentStart(c)) {
      let j = i;
      while (j < n && isIdentChar(text[j])) j++;
      push('IDENT', i, j, text.slice(i, j).toLowerCase());
      i = j;
      continue;
    }
    const two = text.slice(i, i + 2);
    if (two === '>=' || two === '<=' || two === '!=' || two === '==' || two === '<>') {
      push('OP', i, i + 2, two === '==' ? '=' : two === '<>' ? '!=' : two);
      i += 2;
      continue;
    }
    if ('><=+-*/'.includes(c)) {
      push('OP', i, i + 1, c);
      i++;
      continue;
    }
    if ('(),.'.includes(c)) {
      push('PUNCT', i, i + 1, c);
      i++;
      continue;
    }
    const cp = text.codePointAt(i)!;
    const len = cp > 0xffff ? 2 : 1;
    return { toks, error: { code: 'E_UNEXPECTED_CHAR', offset: i, length: len, tok: text.slice(i, i + len) } };
  }
  toks.push({ type: 'EOF', text: '', v: '', num: 0, offset: n, length: 1 });
  return { toks, error: null };
}

/** 1-based line and column of an offset in a text. */
export function lineCol(text: string, offset: number): { line: number; column: number } {
  let line = 1;
  let start = 0;
  for (let i = 0; i < offset && i < text.length; i++) {
    if (text[i] === '\n') {
      line++;
      start = i + 1;
    }
  }
  return { line, column: offset - start + 1 };
}
